class Solution {
public:
    int rob(vector<int>& nums) {
        int prev = 0, cur = 0;  // prev 是 dp[i-2]，cur 是 dp[i-1]
        for (int x : nums) {
            int t = max(cur, prev + x);
            prev = cur;
            cur = t;
        }
        return cur;
    }
};

