class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        vector<int> tails;  // tails[k] 是长度 k+1 的递增子序列的最小结尾
        for (int x : nums) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {  // 第一个大于等于 x 的位置
                int mid = lo + (hi - lo) / 2;
                if (tails[mid] < x) lo = mid + 1;
                else hi = mid;
            }
            if (lo == (int)tails.size()) tails.push_back(x);
            else tails[lo] = x;
        }
        return tails.size();
    }
};

