class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2) return false;
        int target = total / 2;
        vector<bool> dp(target + 1, false);
        dp[0] = true;
        for (int x : nums) {
            for (int j = target; j >= x; j--) {  // 倒序，每件只用一次
                if (dp[j - x]) dp[j] = true;
            }
        }
        return dp[target];
    }
};

