class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        if (n < 2) return s;
        int start = 0, best = 1;
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < 2; k++) {  // 奇数中心 (i,i)、偶数中心 (i,i+1)
                int l = i, r = i + k;
                while (l >= 0 && r < n && s[l] == s[r]) {
                    l--;
                    r++;
                }
                int cur = r - l - 1;
                if (cur > best) {
                    best = cur;
                    start = l + 1;
                }
            }
        }
        return s.substr(start, best);
    }
};

